PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?youngerFilm ?youngerLabel ?birthYounger ?otherFilm ?birthOther WHERE {
  VALUES (?film1 ?film2) { (dbr:The_Tiger_Makes_Out dbr:La_Verite_sur_Bebe_Donge) }

  {
    SELECT ?film1 (MAX(?b1) AS ?b1max) WHERE {
      VALUES (?film1) {(dbr:The_Tiger_Makes_Out)}
      OPTIONAL { ?film1 dbo:director ?d1a. }
      OPTIONAL { ?film1 dbp:director ?d1b. }
      BIND(COALESCE(?d1a, ?d1b) AS ?d1)
      OPTIONAL { ?d1 dbo:birthDate ?b1a. }
      OPTIONAL { ?d1 dbp:birthDate ?b1b. }
      BIND(COALESCE(?b1a, ?b1b) AS ?b1)
      FILTER(bound(?b1) && ?b1 >= "1800-01-01"^^xsd:date && ?b1 <= "2100-01-01"^^xsd:date)
    } GROUP BY ?film1
  }

  {
    SELECT ?film2 (MAX(?b2) AS ?b2max) WHERE {
      VALUES (?film2) {(dbr:La_Verite_sur_Bebe_Donge)}
      OPTIONAL { ?film2 dbo:director ?d2a. }
      OPTIONAL { ?film2 dbp:director ?d2b. }
      BIND(COALESCE(?d2a, ?d2b) AS ?d2)
      OPTIONAL { ?d2 dbo:birthDate ?b2a. }
      OPTIONAL { ?d2 dbp:birthDate ?b2b. }
      BIND(COALESCE(?b2a, ?b2b) AS ?b2)
      FILTER(bound(?b2) && ?b2 >= "1800-01-01"^^xsd:date && ?b2 <= "2100-01-01"^^xsd:date)
    } GROUP BY ?film2
  }

  FILTER(bound(?b1max) && bound(?b2max))

  BIND(IF(?b1max > ?b2max, ?film1, ?film2) AS ?youngerFilm)
  BIND(IF(?b1max > ?b2max, ?b1max, ?b2max) AS ?birthYounger)
  BIND(IF(?b1max > ?b2max, ?film2, ?film1) AS ?otherFilm)
  BIND(IF(?b1max > ?b2max, ?b2max, ?b1max) AS ?birthOther)

  OPTIONAL { ?youngerFilm rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel)='en') }
}
